for name, line, every in (('BNSF', 'BNSF project (including a new Eola Road station)', 20), ('Milwaukee North', 'Milwaukee North project', 30), ('Milwaukee West', 'Milwaukee West project', 30), ('SouthWest Service', 'SouthWest Service project', 30),
                          ('UP North', 'UP North project (including a Peterson/Ridge station)', 20), ('UP Northwest', 'UP Northwest project, which also extends the line 1.6 miles to Johnsburg (not drawn)', 20), ('UP West', 'UP West project', 20)):
    es_line = {'BNSF': 'proyecto BNSF de CMAP (con una nueva estación en Eola Road)', 'UP North': 'proyecto UP North de CMAP (con una estación en Peterson/Ridge)', 'UP Northwest': 'proyecto UP Northwest de CMAP, que además extiende la línea 1.6 millas hasta Johnsburg (no se dibuja),'}.get(name, 'proyecto ' + name + ' de CMAP')
    zh_line = {'BNSF': 'CMAP 的 BNSF 项目（包括新的 Eola Road 站）', 'UP North': 'CMAP 的 UP North 项目（包括 Peterson/Ridge 站）', 'UP Northwest': 'CMAP 的 UP Northwest 项目（还把线路延伸 1.6 英里到 Johnsburg，未绘制）'}.get(name, 'CMAP 的 ' + name + ' 项目')
    pl_line = {'BNSF': 'Projekt CMAP dla BNSF (z nową stacją Eola Road)', 'UP North': 'Projekt CMAP dla UP North (ze stacją Peterson/Ridge)', 'UP Northwest': 'Projekt CMAP dla UP Northwest, który przedłuża też linię o 1,6 mili do Johnsburg (nienarysowane),'}.get(name, 'Projekt CMAP dla ' + name)
    T['CMAP’s ' + line + ' adds track, signals or stations; the preset shows trains every ' + str(every) + ' minutes all day. Metra’s October 2026 draft network plan aims for trains every 15–30 minutes on every line, for about $9 billion.'] = (
        'El ' + es_line + ' agrega vías, señales o estaciones; el preajuste muestra trenes cada ' + str(every) + ' minutos todo el día. El borrador del plan de red de Metra de octubre de 2026 busca trenes cada 15–30 minutos en todas las líneas, por unos $9 mil millones.',
        zh_line + '增加轨道、信号或车站；预设方案显示全天每 ' + str(every) + ' 分钟一班。Metra 2026 年 10 月的网络规划草案目标是每条线每 15–30 分钟一班，约需 90 亿美元。',
        pl_line + ' dodaje tory, sygnalizację lub stacje; gotowa propozycja pokazuje pociągi co ' + str(every) + ' minut przez cały dzień. Projekt planu sieci Metry z października 2026 zakłada pociągi co 15–30 minut na każdej linii, za ok. 9 mld dol.')
