    ['^' + _M + r' in (\d{4}(?: Q\d)?) dollars \(' + _M + r' (.+)\)\.$', '$1 en dólares de $2 ($3 [[$4]]).', '$1，按 $2 美元计（$3 [[$4]]）。', '$1 w dolarach z $2 ($3 [[$4]]).'],
